/**
 * Migration helpers shared by the CLI scripts, the app's setup guard and tests.
 * SQL migrations live in /drizzle and are generated by `npm run db:generate`.
 */
import { migrate } from "drizzle-orm/better-sqlite3/migrator";
import fs from "node:fs";
import path from "node:path";
import type { Connection } from "./client";

export const MIGRATIONS_FOLDER = path.resolve(process.cwd(), "drizzle");

interface Journal {
  entries: Array<{ idx: number; when: number; tag: string }>;
}

function readJournal(): Journal {
  const file = path.join(MIGRATIONS_FOLDER, "meta", "_journal.json");
  return JSON.parse(fs.readFileSync(file, "utf8")) as Journal;
}

export function runMigrations(connection: Connection): void {
  migrate(connection.db, { migrationsFolder: MIGRATIONS_FOLDER });
}

export type DatabaseState =
  | { kind: "ready" }
  | { kind: "uninitialized" }
  | { kind: "pending_migrations"; pending: number }
  | { kind: "empty" };

/** Inspect a connection without changing anything. */
export function inspectDatabase(connection: Connection): DatabaseState {
  const { sqlite } = connection;
  const hasMigrationsTable = sqlite
    .prepare("select 1 from sqlite_master where type = 'table' and name = '__drizzle_migrations'")
    .get();
  if (!hasMigrationsTable) return { kind: "uninitialized" };

  const journal = readJournal();
  const applied = sqlite.prepare("select created_at as createdAt from __drizzle_migrations").all() as Array<{ createdAt: number }>;
  const appliedSet = new Set(applied.map((r) => Number(r.createdAt)));
  const pending = journal.entries.filter((e) => !appliedSet.has(e.when)).length;
  if (pending > 0) return { kind: "pending_migrations", pending };

  const workspace = sqlite.prepare("select 1 from workspaces limit 1").get();
  if (!workspace) return { kind: "empty" };
  return { kind: "ready" };
}
